INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_nvtt_q1', 'Khi hai thuyền trưởng bàn giao xong việc thì:', 'gk2_nvtt', 1), ('gk2_nvtt_q2', 'Bàn giao giấy tờ pháp lý của tàu bao gồm:', 'gk2_nvtt', 2), ('gk2_nvtt_q3', 'Thuyền trưởng có phải trực tiếp phụ trách một ca làm việc trên phương tiện:', 'gk2_nvtt', 3), ('gk2_nvtt_q4', 'Thuyền trưởng mới nhận bàn giao tàu phải:', 'gk2_nvtt', 4), ('gk2_nvtt_q5', 'Quản lý sổ nhật ký hành trình, danh bạ thuyền viên và các sổ sách giấy tờ cần thiết khác của phương tiện là trách nhiệm của:', 'gk2_nvtt', 5), ('gk2_nvtt_q6', 'Quản lý, bảo đảm an toàn về người, phương tiện và tài sản trên phương tiện là trách nhiệm của:', 'gk2_nvtt', 6), ('gk2_nvtt_q7', 'Tổ chức giao nhận hàng hóa, phục vụ hành khách theo lệnh điều động là trách nhiệm của:', 'gk2_nvtt', 7), ('gk2_nvtt_q8', 'Theo tính  pháp lý thuyền trưởng là người có quyền hạng cao nhất:', 'gk2_nvtt', 8), ('gk2_nvtt_q9', 'Ngoài giờ đi ca, nếu thuyền phó hoặc máy trưởng đề nghị, thuyền trưởng phải:', 'gk2_nvtt', 9), ('gk2_nvtt_q10', 'Trường hợp phương tiện bị đắm, sau khi đã thi hành các biện pháp cứu người, tài sản, hàng hoá và các giấy tờ cần thiết của phương tiện thì:', 'gk2_nvtt', 10), ('gk2_nvtt_q11', 'Quy định phân nhóm phương tiện để định biên thuyền viên thì phương tiện chở hàng có trọng tải toàn phần trên 1000 tấn thuộc nhóm:', 'gk2_nvtt', 11), ('gk2_nvtt_q12', 'Quy định phân nhóm phương tiện để định biên thuyền viên thì tàu khách có sức chở trên 50 khách đến 100 khách thuộc nhóm:', 'gk2_nvtt', 12), ('gk2_nvtt_q13', 'Ai sẽ thực hiện nhiệm vụ của thuyền phó nếu không có cơ cấu chức danh thuyền phó trên phương tiện ?', 'gk2_nvtt', 13), ('gk2_nvtt_q14', 'Giấy chứng nhận an toàn kỹ thuật và bảo vệ môi trường ở đâu cấp:', 'gk2_nvtt', 14), ('gk2_nvtt_q15', 'Giấy chứng nhận bảo hiểm ở đâu cấp:', 'gk2_nvtt', 15), ('gk2_nvtt_q16', 'Danh bạ thuyền viên mới do:', 'gk2_nvtt', 16), ('gk2_nvtt_q17', 'Giấy chứng nhận đăng ký phương tiện thủy nội địa ở đâu cấp:', 'gk2_nvtt', 17), ('gk2_nvtt_q18', 'Nhật ký hành trình phải được ghi chép rõ ràng bằng:', 'gk2_nvtt', 18), ('gk2_nvtt_q19', 'Trường hợp nhật ký hành trình ghi bị sai thì thuyền trưởng có thể:', 'gk2_nvtt', 19), ('gk2_nvtt_q20', 'Lập kế hoạch chuyến đi là trách nhiệm của:', 'gk2_nvtt', 20);
